/**
 * SOURCE ONLY: Gannon IRB0318 chairs, shared desks and drawn tier/aisle details.
 * Original HDR/UMD guide[6], unchanged 576 x 576 PDF pt, +Y down.
 * Lean consumer: CHAIRS (centerPt/facingPdf), TABLES (one outline per shared
 * desk), ROWS (six fanned rows), TIER_BOUNDARIES and AISLE_TOPOLOGY.
 * Supporting full source geometry is isolated below in NATIVE_PATHS / STYLES.
 * Native commands/paint remain unchanged; centers and facing are derived from
 * the actual chair symbols. No fitted seats, room polygon or inverse wayfinding.
 * Ground registration, physical chair dimensions/heights and all tier elevations
 * are consumer estimates. No elevation datum or runtime integration is supplied.
 * See docs/research/iribe/gannon-seating-2026-10-03.md at repository root.
 */
export type GannonSeatingPdfPoint = readonly [pdfX: number, pdfY: number];
export type GannonSeatingPdfBounds = readonly [x0: number, y0: number, x1: number, y1: number];
export type GannonSeatingBank = 'north' | 'center' | 'south';
export interface GannonSeatingItemRef {
  readonly pathIndex: number;
  readonly itemIndex: number;
}
export interface GannonSeatingMidpointRef extends GannonSeatingItemRef {
  readonly t: 0.5;
}
export interface GannonSeatingChair {
  readonly id: string;
  readonly role: 'student' | 'presenter';
  readonly bank: GannonSeatingBank | null;
  /** Front to rear in drawing; no associated elevation. */
  readonly rowIndex: number | null;
  readonly tableId: string;
  /** Derived 2D symbol center; this is not a native command vertex. */
  readonly centerPt: GannonSeatingPdfPoint;
  /** Unit vector from chair back toward front in native +Y-down coordinates. */
  readonly facingPdf: GannonSeatingPdfPoint;
  readonly frontMidpointRef: GannonSeatingMidpointRef;
  readonly backMidpointRef: GannonSeatingMidpointRef;
  readonly nativePathIndices: readonly number[];
}
export interface GannonSeatingTable {
  readonly id: string;
  readonly bank: GannonSeatingBank | null;
  readonly rowIndex: number | null;
  /** One actual long outline edge, away from the student chairs. */
  readonly continuousEdge: GannonSeatingItemRef;
  /** Shared fragmented outline, including native duplicate paint and gaps. */
  readonly nativePathIndices: readonly number[];
  readonly chairIds: readonly string[];
}
export type GannonSeatingNativeCommand =
  | readonly ['l', from: GannonSeatingPdfPoint, to: GannonSeatingPdfPoint]
  | readonly ['c', from: GannonSeatingPdfPoint, control1: GannonSeatingPdfPoint,
      control2: GannonSeatingPdfPoint, to: GannonSeatingPdfPoint];
export interface GannonSeatingNativeStyle {
  readonly type: 's';
  readonly color: readonly [number, number, number] | null;
  readonly fill: readonly [number, number, number] | null;
  readonly width: number | null;
  readonly closePath: boolean | null;
  readonly even_odd: boolean | null;
  readonly lineCap: readonly [number, number, number] | null;
  readonly lineJoin: number | null;
  readonly dashes: string | null;
  readonly stroke_opacity: number | null;
  readonly fill_opacity: number | null;
  readonly layer: string;
}
/** Compact supporting tuple. commands[itemIndex] uses the original native index.
 * Full paths are retained. Sort by seqno/pathIndex for source-order replay. */
export type GannonSeatingNativePath = readonly [
  pathIndex: number, seqno: number, boundsPt: GannonSeatingPdfBounds,
  styleIndex: number, commands: readonly GannonSeatingNativeCommand[],
];

// Round-trip decimals deliberately retain the exact original binary floats.
/* eslint-disable no-loss-of-precision */

